record Shape(p: path)
const P: path = segment(start: (0, 0), end: (3, 4))
const Q: path = segment(start: (0, 0), end: (5, 12))
module Pick(p: path, present: boolean) {
 const B: Shape? = if (@present) { Shape(p: @p) }
 export const out: Shape = match @B { some held => @held none => Shape(p: segment(start: (0, 0), end: (7, 24))) }
}
instance One = Pick(p: @P, present: true)
instance Two = Pick(p: @Q, present: false)
const A: path = @One::out.p
const B: path = @Two::out.p
const L: number = @A.length
const M: number = @B.length
const X: number = @A.endPoint.y
const Y: number = @B.endPoint.y

